window.futvizVista("creacion","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"creacion\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"creacion\"]={\"id\":\"creacion\",\"titulo\":\"Ocasiones a favor y en contra\",\"bajada\":\"A la derecha, m\u00e1s xG a favor; arriba, menos xG en contra. Arriba a la derecha dominan las ocasiones.\",\"pregunta\":\"\u00bfQu\u00e9 equipo domina las ocasiones?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_fav\",\"label\":\"xG a favor por partido (sin penales)\",\"corto\":\"xG a favor\",\"dec\":2},\"y\":{\"col\":\"xg_con\",\"label\":\"xG en contra por partido (sin penales); menos, arriba\",\"corto\":\"xG en contra\",\"dec\":2,\"invertir\":true},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"Dominan las ocasiones\",\"tl\":\"Partidos cerrados\",\"br\":\"Partidos abiertos\",\"bl\":\"Dominan los rivales\"}},\"requiere\":[\"xg_fav\",\"xg_con\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG a favor\",\"ayuda\":\"Ordenados por xG a favor por partido (sin penales)\"},{\"id\":\"y\",\"etiqueta\":\"xG en contra\",\"ayuda\":\"Ordenados por xG en contra por partido (sin penales); menos, arriba: primero los que menos ocasiones conceden\"}],\"queMirar\":\"El eje vertical va **al rev\u00e9s** (arriba, menos xG en contra), as\u00ed que arriba a la derecha est\u00e1n los mejores: crean mucho y conceden poco. **Abajo a la derecha**: partidos abiertos. **Arriba a la izquierda**: partidos cerrados. **Abajo a la izquierda**: dominan los rivales.\",\"porQue\":\"Cruza lo que un equipo crea con lo que deja crear: xG de Understat por partido y sin penales, as\u00ed que cuenta ocasiones y no goles, que dependen m\u00e1s del azar.\\n\\nLos dos ejes correlacionan -0.47 sobre 484 equipos-temporada cerrados: van de la mano solo en parte. Los que m\u00e1s crean tienden a conceder menos, pero con mucho margen. De una temporada cerrada a la siguiente, la diferencia de xG por partido de un mismo equipo (lo que crea menos lo que concede) correlaciona entre 0.75 y 0.79, y la de goles, entre 0.67 y 0.74.\",\"insight\":\"creacion\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");